import type { AddedToTeam } from "@surveybeat/domain";
import { Layout, textLayout } from "./Layout.tsx";
import { message } from "./messages/index.ts";
import { BodyText, DisplayHeading, FallbackLink, PrimaryButton } from "./Parts.tsx";

const params = (email: AddedToTeam) => ({ team: email.teamName, lead: email.leadName });

export const subject = (email: AddedToTeam) => message("addedToTeam.subject", params(email));

export function AddedToTeamEmail({ email }: { email: AddedToTeam }) {
  const p = params(email);
  return (
    <Layout preview={message("addedToTeam.preview", p)} reason={message("addedToTeam.reason", p)}>
      <DisplayHeading>{message("addedToTeam.heading", p)}</DisplayHeading>
      <BodyText>{message("addedToTeam.body", p)}</BodyText>
      <PrimaryButton href={email.signInUrl}>{message("addedToTeam.action")}</PrimaryButton>
      <FallbackLink intro={message("addedToTeam.link")} href={email.signInUrl} />
    </Layout>
  );
}

export const text = (email: AddedToTeam): string => {
  const p = params(email);
  return textLayout(
    [
      message("addedToTeam.heading", p),
      "",
      message("addedToTeam.body", p),
      "",
      `${message("addedToTeam.action")}: ${email.signInUrl}`,
    ],
    message("addedToTeam.reason", p),
  );
};
import type { InvitationEmailWithToken as InvitationEmailData } from "@surveybeat/domain";
import { Layout, textLayout } from "./Layout.tsx";
import { message } from "./messages/index.ts";
import { ActionRow, ActionsCard, DisplayHeading, Notices, PrivacyPanel, RatingRow } from "./Parts.tsx";

/** The AI notice, present only when the Organization processes comments with AI (ADR 0015). */
const aiNotice = (email: InvitationEmailData): string | undefined =>
  email.aiProcessing === true ? message("privacy.aiNotice") : undefined;

/**
 * What the lead will and will not see (SPEC 5.2). Rows stored before N was carried hold the finished
 * statement instead; they render verbatim.
 */
const anonymityStatement = (email: InvitationEmailData): string =>
  email.minimumGroupSize === undefined
    ? (email.anonymityStatement ?? "")
    : message("invitation.anonymity", { n: email.minimumGroupSize });

export const subject = (email: InvitationEmailData): string =>
  message("invitation.subject", { pulse: email.pulseName });

export function InvitationEmailComponent({ email }: { email: InvitationEmailData }) {
  const openUrl = `${email.baseUrl}/a#t=${email.token}`;
  const deliveryUrl = `${email.baseUrl}/delivery?token=${email.token}`;
  const notice = aiNotice(email);

  return (
    <Layout
      preview={message("invitation.preview", { pulse: email.pulseName })}
      reason={message("invitation.reason")}
      outside={
        <>
          <ActionsCard actions={email.actions} />
          <PrivacyPanel>
            {anonymityStatement(email)}
            {notice !== undefined && (
              <>
                <br />
                {notice}
              </>
            )}
          </PrivacyPanel>
          <Notices deliveryUrl={deliveryUrl} />
        </>
      }
    >
      <DisplayHeading>{email.pulseName}</DisplayHeading>
      {email.ratingQuestion && (
        <RatingRow question={email.ratingQuestion} baseUrl={email.baseUrl} token={email.token} />
      )}
      <ActionRow href={openUrl} />
    </Layout>
  );
}

export const text = (email: InvitationEmailData): string => {
  const openUrl = `${email.baseUrl}/a#t=${email.token}`;
  const deliveryUrl = `${email.baseUrl}/delivery?token=${email.token}`;
  const notice = aiNotice(email);

  const ratingLines: Array<string> = [];
  if (email.ratingQuestion) {
    ratingLines.push(email.ratingQuestion.text, "");
    for (let val = 1; val <= 5; val++) {
      const label =
        val === 1
          ? `1 (${email.ratingQuestion.lowLabel})`
          : val === 5
            ? `5 (${email.ratingQuestion.highLabel})`
            : `${val}`;
      ratingLines.push(`${label}: ${email.baseUrl}/a#t=${email.token}&v=${val}`);
    }
    ratingLines.push("");
  }

  const actionLines: Array<string> = [];
  if (email.actions.length > 0) {
    actionLines.push(message("invitation.actionsHeading"));
    for (const act of email.actions.slice(0, 3)) {
      actionLines.push(`• ${act}`);
    }
    actionLines.push("");
  }

  return textLayout(
    [
      email.pulseName,
      "",
      anonymityStatement(email),
      ...(notice === undefined ? [] : [notice]),
      "",
      ...ratingLines,
      `${message("invitation.openCheckIn")}: ${openUrl}`,
      "",
      ...actionLines,
      `${message("invitation.changeWhen")}: ${deliveryUrl}`,
      message("invitation.personalNotice"),
    ],
    message("invitation.reason"),
  );
};
import type { ReminderEmailWithToken as ReminderEmailData } from "@surveybeat/domain";
import { Link } from "react-email";
import { Layout, textLayout } from "./Layout.tsx";
import { message } from "./messages/index.ts";
import {
  ActionRow,
  ActionsCard,
  BodyText,
  DisplayHeading,
  FooterNote,
  Notices,
  RatingRow,
} from "./Parts.tsx";
import { colors } from "./theme.ts";

/** Legacy rows carry their own URL; otherwise it is built from the token. */
export const unsubscribeUrl = (email: ReminderEmailData): string =>
  email.unsubscribeUrl ?? `${email.baseUrl}/api/reminders/unsubscribe?t=${email.token}`;

export const subject = (email: ReminderEmailData): string =>
  message("reminder.subject", { pulse: email.pulseName });

export function ReminderEmailComponent({ email }: { email: ReminderEmailData }) {
  const openUrl = `${email.baseUrl}/a#t=${email.token}`;
  const deliveryUrl = `${email.baseUrl}/delivery?token=${email.token}`;

  return (
    <Layout
      preview={message("reminder.preview", { pulse: email.pulseName })}
      reason={message("invitation.reason")}
      outside={
        <>
          <ActionsCard actions={email.actions ?? []} />
          <Notices
            deliveryUrl={deliveryUrl}
            extra={
              <>
                <br />
                <Link
                  className="sb-link"
                  href={unsubscribeUrl(email)}
                  style={{ color: colors.accent, textDecoration: "underline" }}
                >
                  {message("reminder.unsubscribe")}
                </Link>
              </>
            }
          />
          {email.aiProcessing === true && <FooterNote>{message("privacy.aiNotice")}</FooterNote>}
        </>
      }
    >
      <DisplayHeading>{message("reminder.heading", { pulse: email.pulseName })}</DisplayHeading>
      <BodyText>{message("reminder.body")}</BodyText>
      {email.ratingQuestion && (
        <RatingRow question={email.ratingQuestion} baseUrl={email.baseUrl} token={email.token} />
      )}
      <ActionRow href={openUrl} />
    </Layout>
  );
}

export const text = (email: ReminderEmailData): string => {
  const openUrl = `${email.baseUrl}/a#t=${email.token}`;
  const deliveryUrl = `${email.baseUrl}/delivery?token=${email.token}`;

  const ratingLines: Array<string> = [];
  if (email.ratingQuestion) {
    ratingLines.push(email.ratingQuestion.text, "");
    for (let val = 1; val <= 5; val++) {
      const label =
        val === 1
          ? `1 (${email.ratingQuestion.lowLabel})`
          : val === 5
            ? `5 (${email.ratingQuestion.highLabel})`
            : `${val}`;
      ratingLines.push(`${label}: ${email.baseUrl}/a#t=${email.token}&v=${val}`);
    }
    ratingLines.push("");
  }

  const actionLines: Array<string> = [];
  if (email.actions.length > 0) {
    actionLines.push(message("invitation.actionsHeading"));
    for (const act of email.actions.slice(0, 3)) {
      actionLines.push(`• ${act}`);
    }
    actionLines.push("");
  }

  return textLayout(
    [
      message("reminder.heading", { pulse: email.pulseName }),
      "",
      message("reminder.body"),
      "",
      ...ratingLines,
      `${message("invitation.openCheckIn")}: ${openUrl}`,
      "",
      ...actionLines,
      `${message("invitation.changeWhen")}: ${deliveryUrl}`,
      `${message("reminder.unsubscribe")}: ${unsubscribeUrl(email)}`,
      ...(email.aiProcessing === true ? [message("privacy.aiNotice")] : []),
      message("invitation.personalNotice"),
    ],
    message("invitation.reason"),
  );
};
