const d = darkColors;

/** Clients that honour `prefers-color-scheme` swap to the dark palette through the classes below. */
const darkMode = `
:root { color-scheme: light dark; supported-color-schemes: light dark; }
@media (prefers-color-scheme: dark) {
  .sb-page { background-color: ${d.page} !important; }
  .sb-card { background-color: ${d.card} !important; border-color: ${d.border} !important; }
  .sb-text { color: ${d.text} !important; }
  .sb-muted { color: ${d.muted} !important; }
  .sb-rule { border-color: ${d.rowBorder} !important; }
  .sb-button { background-color: ${d.button} !important; color: ${d.buttonText} !important; }
  .sb-link { color: ${d.link} !important; }
  .sb-panel { background-color: ${d.panel} !important; }
  .sb-panel-text { color: ${d.panelText} !important; }
  .sb-rating { border-color: ${d.ratingBorder} !important; color: ${d.ratingText} !important; }
}
`;

/** The frame every SurveyBeat email shares: preview line, brand, card, and the reason it was sent. */
export function Layout({
  preview,
  reason,
  children,
  outside,
}: {
  preview: string;
  reason: string;
  children: ReactNode;
  /** Extra blocks between the card and the footer, such as the privacy panel. */
  outside?: ReactNode;
}) {
  return (
    <Html lang="en">
      <Head>
        <meta name="color-scheme" content="light dark" />
        <meta name="supported-color-schemes" content="light dark" />
        <style>{darkMode}</style>
      </Head>
      <Preview>{preview}</Preview>
      <Body
        className="sb-page"
        style={{ backgroundColor: colors.page, fontFamily: fonts.sans, margin: 0, padding: "40px 0" }}
      >
        <Container style={{ maxWidth: "560px", padding: "0 20px" }}>
          <Text
            className="sb-muted"
            style={{ color: colors.muted, fontSize: "15px", fontWeight: 600, margin: "0 0 16px 8px" }}
          >
            {message("layout.brand")}
          </Text>
          <Section
            className="sb-card"
            style={{
              backgroundColor: colors.card,
              border: `1px solid ${colors.border}`,
              borderRadius: radius.card,
              padding: "40px 36px",
            }}
          >
            {children}
          </Section>
          {outside}
          <Hr
            className="sb-rule"
            style={{ borderTop: `1px solid ${colors.border}`, margin: "24px 0 12px" }}
          />
          <Text
            className="sb-muted"
            style={{ color: colors.muted, fontSize: "12px", lineHeight: "18px", margin: 0 }}
          >
            {reason}
          </Text>
          <Text
            className="sb-muted"
            style={{ color: colors.muted, fontSize: "12px", lineHeight: "18px", margin: "4px 0 0" }}
          >
            {message("layout.signature")}
          </Text>
        </Container>
      </Body>
    </Html>
  );
}

/** The plain-text part's frame, mirroring `Layout`. */
export const textLayout = (body: ReadonlyArray<string>, reason: string): string =>
  [...body, "", "--", reason, message("layout.signature"), ""].join("\n");
import {
  EmailTemplates,
  InvitationTokens,
  type RenderableEmail,
  type RenderedEmail,
  withToken,
} from "@surveybeat/domain";
import { Effect, Layer } from "effect";
import { render } from "react-email";
import * as AddedToTeam from "./AddedToTeam.tsx";
import * as InvitationEmail from "./InvitationEmail.tsx";
import * as ReminderEmail from "./ReminderEmail.tsx";
import * as ResultsReadyEmail from "./ResultsReadyEmail.tsx";

/** A subject is one header line: names with line breaks must not start another header. */
const oneLine = (subject: string) => subject.replace(/\s*[\r\n]+\s*/g, " ");

/** Renders the HTML and plain-text parts. Adding a `RenderableEmail` variant fails to compile here. */
export const renderEmail = async (email: RenderableEmail): Promise<RenderedEmail> => {
  switch (email._tag) {
    case "AddedToTeam":
      return {
        subject: oneLine(AddedToTeam.subject(email)),
        html: await render(<AddedToTeam.AddedToTeamEmail email={email} />),
        text: AddedToTeam.text(email),
      };
    case "InvitationEmail":
      return {
        subject: oneLine(InvitationEmail.subject(email)),
        html: await render(<InvitationEmail.InvitationEmailComponent email={email} />),
        text: InvitationEmail.text(email),
      };
    case "ReminderEmail":
      return {
        subject: oneLine(ReminderEmail.subject(email)),
        html: await render(<ReminderEmail.ReminderEmailComponent email={email} />),
        text: ReminderEmail.text(email),
        headers: {
          "List-Unsubscribe": `<${ReminderEmail.unsubscribeUrl(email)}>`,
          "List-Unsubscribe-Post": "List-Unsubscribe=One-Click",
        },
      };
    case "ResultsReadyEmail":
      return {
        subject: oneLine(ResultsReadyEmail.subject(email)),
        html: await render(<ResultsReadyEmail.ResultsReadyEmailComponent email={email} />),
        text: ResultsReadyEmail.text(email),
      };
  }
};

/**
 * The domain's `EmailTemplates`, rendered with React Email. The token an Invitation or reminder
 * refers to is derived here, just before rendering, so it is never stored. A render failure is a defect.
 */
export const EmailTemplatesLive = Layer.effect(
  EmailTemplates,
  Effect.gen(function* () {
    const tokens = yield* InvitationTokens;
    return {
      render: (email) =>
        withToken(email).pipe(
          Effect.provideService(InvitationTokens, tokens),
          Effect.flatMap((renderable) => Effect.promise(() => renderEmail(renderable))),
        ),
    };
  }),
);
export { EmailTemplatesLive, renderEmail } from "./render.tsx";

